/**
 * LeadPanel -- the persistent universe-discovery panel (AMGT-rd-8 deliverable (a)).
 *
 * PERSISTENT: rendered once by `SecurityAnalysis.tsx`, above the tab bar; it stays
 * mounted while Thesis/Peers/Coverage change beneath it (task order BLOCK).
 *
 * Mode dropdown: `Trending | Breakout | Starred` + a ticker search that enters
 * Security mode (CTO synthesis s.3's own dropdown shape: "Trending | Breakout |
 * Starred | -- | (search any ticker)").
 *
 * Trending/Breakout mapping (DESIGN_DECISIONS.md in this cell's deliverable):
 * MEASURED live 2026-09-11 -- the metrics table (`opal-harvest-security-metrics`,
 * RENAMED from `opal-amgt-security-metrics` ~20:1xZ, same session; the old name is
 * DROPPED and no longer resolves) carries exactly two axis values, CHATTER and PRICE
 * (no TRENDING#/BREAKOUT# row has ever been written, before or after the rename --
 * re-verified against the renamed table). This
 * panel therefore maps Trending -> the CHATTER axis (spiking in discussion) and
 * Breakout -> the PRICE axis (moving in price) 1:1 -- both are pre-computed,
 * producer-ranked reads; neither label re-derives anything the other does not.
 *
 * List/Chart toggle applies to Trending/Breakout (Starred is List-only at this cut,
 * see `StarredList.tsx`). Refresh is an explicit action, NOT wired to starring.
 *
 * Dark-container-only (white idiom): this whole panel is `Panel variant="mixed"`.
 */

import { type FC, type FormEvent } from 'react'
import { LayoutList, LineChart as ChartIcon, RefreshCw, Search } from 'lucide-react'
import { Panel, PanelHeader, PanelContent } from '@/ui/components/panels'
import { Select } from '@/ui/components/Select'
import { useAuth } from '@/hooks/useAuth'
import {
  useLeadPanelRankings,
  useStarredList,
  useSetStarred,
  useRequestRefresh,
  useSecurityOverlay,
} from '../hooks/useLeadPanelApi'
import type { LeadPanelView } from '../hooks/useSecurityAnalysisState'
import type { LeadPanelMode, ChatterRankingRow, PriceRankingRow } from '../types'
import { RankedList } from './RankedList'
import { RankedChart } from './RankedChart'
import { StarredList } from './StarredList'
import { SecurityOverlay } from './SecurityOverlay'

export interface LeadPanelProps {
  mode: LeadPanelMode
  setMode: (mode: LeadPanelMode) => void
  view: LeadPanelView
  setView: (view: LeadPanelView) => void
  selectedSecurityKey: string | null
  onSelectSecurity: (securityKey: string) => void
  onClearSecuritySelection: () => void
  searchInput: string
  setSearchInput: (v: string) => void
}

const MODE_OPTIONS = [
  { value: 'trending', label: 'Trending' },
  { value: 'breakout', label: 'Breakout' },
  { value: 'starred', label: 'Starred' },
]

export const LeadPanel: FC<LeadPanelProps> = ({
  mode,
  setMode,
  view,
  setView,
  selectedSecurityKey,
  onSelectSecurity,
  onClearSecuritySelection,
  searchInput,
  setSearchInput,
}) => {
  const { claims } = useAuth()
  const firmId = claims?.firmId ?? undefined

  const chatterQuery = useLeadPanelRankings('trending')
  const breakoutQuery = useLeadPanelRankings('breakout')
  const starredQuery = useStarredList(firmId)
  const setStarredMutation = useSetStarred(firmId)
  const refreshMutation = useRequestRefresh()
  const overlayQuery = useSecurityOverlay(selectedSecurityKey)

  const starredTickers = new Set((starredQuery.data ?? []).map((e) => e.ticker))

  const handleToggleStar = (ticker: string) => {
    setStarredMutation.mutate({ ticker, starred: !starredTickers.has(ticker) })
  }

  const handleSearchSubmit = (e: FormEvent) => {
    e.preventDefault()
    const ticker = searchInput.trim()
    if (ticker) {
      onSelectSecurity(ticker)
    }
  }

  const isSecurityMode = selectedSecurityKey !== null
  const activeRankingQuery = mode === 'trending' ? chatterQuery : breakoutQuery

  return (
    <Panel variant="mixed">
      <PanelHeader
        title="Lead Panel"
        subtitle="Universe discovery -- ranked server-side, read here, never re-derived"
        timestamp={activeRankingQuery.data?.generated_at ?? null}
        source={mode === 'trending' ? 'chatter axis (AMGT-rd-5)' : 'price axis (AMGT-rd-6)'}
        actions={
          <div className="flex items-center gap-3">
            {!isSecurityMode && (
              <>
                <Select
                  label="Mode"
                  value={mode}
                  options={MODE_OPTIONS}
                  onChange={(v) => setMode(v as LeadPanelMode)}
                />
                {mode !== 'starred' && (
                  <div className="flex items-center gap-1 rounded-lg bg-white/10 p-1">
                    <button
                      type="button"
                      onClick={() => setView('list')}
                      className={`p-1.5 rounded ${view === 'list' ? 'bg-[hsl(var(--primary))] text-white' : 'text-white/60'}`}
                      aria-label="List view"
                    >
                      <LayoutList size={14} />
                    </button>
                    <button
                      type="button"
                      onClick={() => setView('chart')}
                      className={`p-1.5 rounded ${view === 'chart' ? 'bg-[hsl(var(--primary))] text-white' : 'text-white/60'}`}
                      aria-label="Chart view"
                    >
                      <ChartIcon size={14} />
                    </button>
                  </div>
                )}
              </>
            )}
            <form onSubmit={handleSearchSubmit} className="flex items-center gap-1.5">
              <div className="relative">
                <Search size={12} className="absolute left-2 top-1/2 -translate-y-1/2 text-white/40" />
                <input
                  type="text"
                  value={searchInput}
                  onChange={(e) => setSearchInput(e.target.value)}
                  placeholder="Search any ticker"
                  className="pl-6 pr-2 py-1.5 rounded-lg bg-white/10 border border-white/20 text-white text-xs placeholder:text-white/30 focus:outline-none focus:ring-2 focus:ring-[hsl(var(--primary))] w-36"
                />
              </div>
            </form>
            {isSecurityMode && selectedSecurityKey && (
              <button
                type="button"
                onClick={() => refreshMutation.mutate(selectedSecurityKey)}
                disabled={refreshMutation.isPending}
                className="flex items-center gap-1.5 px-2.5 py-1.5 rounded-lg bg-white/10 text-white text-xs hover:bg-white/20 disabled:opacity-50 transition-colors"
              >
                <RefreshCw size={12} className={refreshMutation.isPending ? 'animate-spin' : ''} />
                Refresh
              </button>
            )}
          </div>
        }
      />
      <PanelContent>
        {isSecurityMode ? (
          <SecurityOverlay
            bundle={overlayQuery.data}
            isLoading={overlayQuery.isLoading}
            onClose={onClearSecuritySelection}
          />
        ) : mode === 'starred' ? (
          <StarredList
            starredTickers={Array.from(starredTickers)}
            chatterRows={(chatterQuery.data?.rows ?? []) as ChatterRankingRow[]}
            priceRows={(breakoutQuery.data?.rows ?? []) as PriceRankingRow[]}
            onUnstar={handleToggleStar}
            onSelectSecurity={onSelectSecurity}
            isLoading={starredQuery.isLoading}
          />
        ) : view === 'list' ? (
          <RankedList
            rows={activeRankingQuery.data?.rows ?? []}
            starredTickers={starredTickers}
            onToggleStar={handleToggleStar}
            onSelectSecurity={onSelectSecurity}
            isLoading={activeRankingQuery.isLoading}
          />
        ) : (
          <RankedChart rows={activeRankingQuery.data?.rows ?? []} isLoading={activeRankingQuery.isLoading} />
        )}
      </PanelContent>
    </Panel>
  )
}

