/**
 * StarredList -- Lead Panel's Starred mode.
 *
 * "Starred mode: same List/Chart, filtered to the PM-starred set; pure saved-view
 * filter, no ranking math" (CTO synthesis s.3). This is a FILTER over the two
 * already-producer-ranked axes (chatter + price), never a re-rank: both axes' rows
 * are fetched once by `LeadPanel` and filtered here to `starredTickers` with
 * `.filter()` -- producer order preserved, nothing resorted or rescored.
 *
 * SCOPED SIMPLIFICATION, stated plainly: this cut renders Starred as a two-column
 * List only (chatter + price side by side per name); the Chart view toggle applies
 * to Trending/Breakout, not Starred, at this cut -- FWD-15's own DONE WHEN test is
 * "opens the page, reads a ranked list, clicks through to a name," which a starred
 * List view already satisfies. A Starred Chart view is a follow-on, not a cut corner
 * on the cell's own bound.
 *
 * Dark-container-only (white idiom).
 */

import { type FC } from 'react'
import { Star } from 'lucide-react'
import type { ChatterRankingRow, PriceRankingRow } from '../types'

export interface StarredListProps {
  starredTickers: string[]
  chatterRows: ChatterRankingRow[]
  priceRows: PriceRankingRow[]
  onUnstar: (ticker: string) => void
  onSelectSecurity: (ticker: string) => void
  isLoading?: boolean
}

export const StarredList: FC<StarredListProps> = ({
  starredTickers,
  chatterRows,
  priceRows,
  onUnstar,
  onSelectSecurity,
  isLoading,
}) => {
  if (isLoading) {
    return <div className="text-sm text-white/50 py-4">Loading starred names…</div>
  }

  if (starredTickers.length === 0) {
    return (
      <div className="text-sm text-white/50 py-4">
        No starred names yet. Star a name from Trending or Breakout to save it here --
        shared across the firm (both PMs see the same starred set).
      </div>
    )
  }

  const chatterByTicker = new Map(chatterRows.map((r) => [r.ticker, r]))
  const priceByTicker = new Map(priceRows.map((r) => [r.ticker, r]))

  return (
    <ol className="divide-y divide-white/10">
      {starredTickers.map((ticker) => {
        const chatter = chatterByTicker.get(ticker)
        const price = priceByTicker.get(ticker)
        return (
          <li
            key={ticker}
            className="flex items-center gap-3 py-2 cursor-pointer"
            onClick={() => onSelectSecurity(ticker)}
          >
            <button
              type="button"
              onClick={(e) => {
                e.stopPropagation()
                onUnstar(ticker)
              }}
              className="flex-shrink-0 text-amber-400 hover:text-amber-300 transition-colors"
              aria-label="Unstar"
            >
              <Star size={14} className="fill-amber-400" />
            </button>
            <div className="flex-1 min-w-0">
              <div className="text-sm font-medium text-white truncate">{ticker}</div>
            </div>
            <div className="text-xs text-white/50 whitespace-nowrap">
              {chatter ? `chatter #${chatter.rank}` : 'not in today\'s chatter rows'}
            </div>
            <div className="text-xs text-white/50 whitespace-nowrap">
              {price ? `price #${price.rank} (${price.score >= 0 ? '+' : ''}${price.score.toFixed(1)}%)` : 'not in today\'s price rows'}
            </div>
          </li>
        )
      })}
    </ol>
  )
}
